'use client';

import { useState } from 'react';
import { useSession } from '@/hooks/useSession';
import { useRouter } from 'next/navigation';

export default function SessionPage() {
    const [username, setUsername] = useState('');
    const { createSession, loading, error } = useSession();
    const router = useRouter();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!username.trim()) return;

        await createSession(username);
        router.push('/rooms');
    };

    return (
        <div className="min-h-screen bg-white flex flex-col items-center justify-center p-4">
            <div className="max-w-md w-full text-center">
                <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
                    <span className="text-white text-3xl">🔒</span>
                </div>

                <h1 className="text-3xl font-bold text-gray-900 mb-2">Temporary Identity</h1>
                <p className="text-gray-500 mb-8">
                    Enter a pseudonym for this session. It will be discarded when you leave.
                </p>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <input
                        type="text"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        placeholder="e.g. Secret Agent 007"
                        className="w-full px-5 py-4 bg-gray-50 text-black border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition"
                        autoFocus
                    />

                    {error && (
                        <p className="text-red-500 text-sm">{error}</p>
                    )}

                    <button
                        type="submit"
                        disabled={loading || !username.trim()}
                        className="w-full bg-gray-900 text-white font-medium py-4 rounded-xl hover:bg-gray-800 transition disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {loading ? 'Creating Identity...' : 'Start Secure Session →'}
                    </button>
                </form>

                <p className="mt-8 text-xs text-center text-gray-400">
                    By continuing, you agree to our ephemeral data policy.
                </p>
            </div>
        </div>
    );
}
