import { useState, useEffect, useCallback } from 'react';
import { UserService } from '@/services/user.service';
import { SessionService } from '@/services/session.service';
import { User, UserPayload } from '@/types/user';
import { Session } from '@/types/session'; // Correct import for Session type
import { ID } from 'appwrite';

const STORAGE_KEY_USER = 'nexconnect_user_id';
const STORAGE_KEY_SESSION = 'nexconnect_session_private_id';

export function useSession() {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const initSession = useCallback(async () => {
        setLoading(true);
        try {
            const userId = localStorage.getItem(STORAGE_KEY_USER);
            // const privateId = localStorage.getItem(STORAGE_KEY_SESSION);

            if (userId) {
                const userDoc = await UserService.get(userId);
                setUser(userDoc);
            }

            // Note: Since SessionService.get isn't defined in the provided snippets, 
            // we assume for now we primarily track the User. 
            // If Session validation is needed, we would add it here.

        } catch (err) {
            console.error('Session initialization failed:', err);
            // If user not found, clear storage
            localStorage.removeItem(STORAGE_KEY_USER);
            localStorage.removeItem(STORAGE_KEY_SESSION);
            setUser(null);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        initSession();
    }, [initSession]);

    const createSession = async (username: string) => {
        setLoading(true);
        setError(null);
        try {
            const userId = ID.unique();
            const userPayload: UserPayload = {
                userId,
                username,
                isGuest: true,
            };

            const newUser = await UserService.create(userPayload);
            setUser(newUser);
            localStorage.setItem(STORAGE_KEY_USER, userId);

            // Create a session document (optional, based on your architecture)
            const privateId = ID.unique();
            const sessionPayload = {
                userId,
                privateId,
                expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // 24 hours
            };
            const newSession = await SessionService.create(sessionPayload);
            setSession(newSession);
            localStorage.setItem(STORAGE_KEY_SESSION, privateId);

        } catch (err: any) {
            console.error('Create session failed:', err);
            setError(err.message || 'Failed to create session');
        } finally {
            setLoading(false);
        }
    };

    const logout = async () => {
        setLoading(true);
        try {
            if (session) {
                await SessionService.expire(session.$id);
            }
            setUser(null);
            setSession(null);
            localStorage.removeItem(STORAGE_KEY_USER);
            localStorage.removeItem(STORAGE_KEY_SESSION);
        } catch (err) {
            console.error('Logout failed:', err);
        } finally {
            setLoading(false);
        }
    };

    return {
        user,
        session,
        loading,
        error,
        createSession,
        logout,
        isAuthenticated: !!user,
    };
}
